// One item with a unique list of websites for the email finder
const websites = [...new Set(
  $input.all().map(i => i.json.website).filter(Boolean)
)];
if (websites.length === 0) return [];
return [{ json: { websites } }];

// Keep rows that found an email, then send one unique list to the verifier
const emails = [...new Set(
  $input.all()
    .filter(i => i.json.resultType === 'email' && i.json.email)
    .map(i => i.json.email.toLowerCase())
)];
if (emails.length === 0) return [];
return [{ json: { emails } }];

// Join the three actor outputs: business (Maps) + email (finder) + verdict (verifier)
const host = (u) => String(u || '').toLowerCase().replace(/^[a-z]+:\/\//, '').split(/[\/?#:]/)[0].replace(/^www\./, '');

const businessByDomain = {};
for (const item of $('Scrape Google Maps').all()) {
  const d = host(item.json.website);
  if (d && !businessByDomain[d]) businessByDomain[d] = item.json;
}

const verdictByEmail = {};
for (const item of $input.all()) {
  if (item.json.email) verdictByEmail[item.json.email.toLowerCase()] = item.json;
}

const keepCatchAll = $('Set search').first().json.keepCatchAll;
const rows = [];
const seen = new Set();

for (const item of $('Find emails on websites').all()) {
  const f = item.json;
  if (f.resultType !== 'email' || !f.email) continue;
  const email = f.email.toLowerCase();
  if (seen.has(email)) continue;
  seen.add(email);

  const v = verdictByEmail[email] || {};
  const status = v.result || 'unknown';
  if (status !== 'ok' && !(keepCatchAll && status === 'catch_all')) continue;

  const b = businessByDomain[f.domain || host(f.website)] || {};
  rows.push({ json: {
    business: b.name || '',
    category: b.category || '',
    email,
    email_status: status,
    phone: b.phone || '',
    website: b.website || f.website || '',
    address: b.address || '',
    rating: b.rating ?? '',
    reviews: b.reviews ?? '',
    maps_url: b.mapsUrl || '',
    email_source: (f.sourceUrls || [])[0] || '',
    found_at: new Date().toISOString(),
  }});
}
return rows;
